      "ids": ["EFF-01"],
      "type": "resource",
      "description": "EFF-01's focus on reducing travel time may lead to shortcuts in data handling and security practices, risking user data integrity."
    },
    {
      "ids": ["EFF-07"],
      "type": "resource",
      "description": "EFF-07's prioritization of smoothness during emergency maneuvers could conflict with the need for secure data logging and auditability during critical situations."
    }
  ],
